<script setup lang="ts">
import type { Content, ContentType, Details, MediaAsset, Taxon, Category } from '~/types'
import { sectionOf, sections, statusText, contentUrl } from '~/utils/site'
import { NSelect, NModal, useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin', key: route => route.path })
const route = useRoute(), api = useApi(), message = useMessage(), confirm = useConfirm()
const existingId = route.params.id === 'new' ? null : Number(route.params.id)
const item = ref<Content | null>(existingId ? await api<Content>(`/api/admin/contents/${existingId}`) : null)
const initialType = (item.value?.contentType || route.query.type || 'article') as ContentType
if (!sections.some(s => s.type === initialType)) throw createError({ statusCode: 404, message: '内容类型不存在' })
if (item.value?.deletedAt) { await navigateTo(`/admin/${sectionOf(initialType).path}?status=trash`); }
const defaults = (): Details => ({ demoUrl: '', sourceUrl: '', projectStatus: 'developing', techStack: [], difficulty: 'beginner', prerequisitesMarkdown: '', claimUrl: '', benefitText: '', requirementsMarkdown: '', startsAt: null, endsAt: null, chapters: [] })
function writableDetails(details?: Details): Details {
  const result = { ...defaults(), ...details }; delete result.validity; delete result.verification
  return result
}
const form = reactive({ type: initialType, slug: item.value?.slug || '', title: item.value?.title || '', summary: item.value?.summary || '', bodyMarkdown: item.value?.bodyMarkdown || '',
  lockVersion: item.value?.lockVersion || 0, changeNote: '', tagIds: item.value?.tagIds || [], categoryId: item.value?.categoryId || null, coverAssetId: item.value?.coverAssetId || null,
  galleryAssetIds: item.value?.galleryAssetIds || [], details: writableDetails(item.value?.details) })
const snapshot = ref(JSON.stringify(form)), dirty = computed(() => snapshot.value !== JSON.stringify(form)), busy = ref(false), previewInline = ref(false)
const picker = ref(false), pickUsage = ref<'body' | 'cover' | 'gallery'>('body'), bodyInput = ref<HTMLTextAreaElement | null>(null)
const { data: taxonomy } = await useFetch<{ tags: Taxon[]; categories: Category[] }>('/api/admin/taxonomy')
const tags = computed(() => taxonomy.value?.tags.map(t => ({ label: t.name, value: t.id })) || [])
const typeOptions = sections.map(s => ({ label: s.label, value: s.type }))
const categories = computed(() => (taxonomy.value?.categories || []).map((c: Category) => ({ label: c.name, value: c.id })))
const revisions = ref<{ id: number; revisionNo: number; title: string; revisionState: string; changeNote?: string }[]>([])
const showHistory = ref(false)
useUnsavedChanges(dirty); useSeoMeta({ title: () => `${item.value ? '编辑' : '新建'}${sectionOf(form.type).label}` })
async function save(publish = false) {
  if (form.slug && !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(form.slug)) { message.error('访问地址只能用小写英文、数字和连字符'); return }
  if (publish && !await confirm('确认发布？', item.value?.publishStatus === 'published' ? '保存当前修改并更新公开版本，访客将看到这一版内容。' : '保存当前内容并对访客公开。')) return
  busy.value = true
  try {
    const id = item.value?.id
    // Categories are article-only; never send a stale categoryId for other types.
    if (form.type !== 'article') form.categoryId = null
    const payload = JSON.parse(JSON.stringify(form)); if (!payload.slug) payload.slug = null
    const saved = await api<Content>(id ? `/api/admin/contents/${id}` : '/api/admin/contents', { method: id ? 'PUT' : 'POST', body: payload })
    item.value = saved; form.lockVersion = saved.lockVersion!; snapshot.value = JSON.stringify(form)
    if (publish) {
      item.value = await api<Content>(`/api/admin/contents/${saved.id}/publish`, { method: 'POST', body: { lockVersion: saved.lockVersion } })
      form.lockVersion = item.value.lockVersion!; snapshot.value = JSON.stringify(form)
    }
    message.success(publish ? '内容已发布，前台已经更新' : '草稿已保存，公开版本保持原样')
    if (!existingId) await navigateTo(`/admin/editor/${saved.id}`, { replace: true })
  } catch (e) { message.error(errorText(e)) } finally { busy.value = false }
}
async function history() { if (!item.value) return; try { revisions.value = await api(`/api/admin/contents/${item.value.id}/revisions`); showHistory.value = true } catch (e) { message.error(errorText(e)) } }
function insert(text: string) { const node = bodyInput.value; const start = node?.selectionStart ?? form.bodyMarkdown.length, end = node?.selectionEnd ?? start; form.bodyMarkdown = form.bodyMarkdown.slice(0, start) + text + form.bodyMarkdown.slice(end); nextTick(() => { node?.focus(); node?.setSelectionRange(start + text.length, start + text.length) }) }
function pick(usage: typeof pickUsage.value) { pickUsage.value = usage; picker.value = true }
function chosen(asset: MediaAsset) { if (pickUsage.value === 'cover') form.coverAssetId = asset.id; else if (pickUsage.value === 'gallery') form.galleryAssetIds = [...new Set([...form.galleryAssetIds, asset.id])]; else insert(`\n![图片说明](/api/public/media/${asset.id})\n`) }
function addChapter() { form.details.chapters!.push({ chapterKey: crypto.randomUUID(), slug: `chapter-${Date.now().toString(36)}`, title: '', bodyMarkdown: '' }) }
function moveChapter(index: number, offset: number) { const list = form.details.chapters!; const [chapter] = list.splice(index, 1); list.splice(index + offset, 0, chapter!) }
function datetime(value?: string | null) { if (!value) return ''; return new Date(new Date(value).getTime() + 8 * 3600000).toISOString().slice(0, 16) }
function setDate(key: 'startsAt' | 'endsAt', event: Event) { const value = (event.target as HTMLInputElement).value; form.details[key] = value ? `${value}:00+08:00` : null }
const techText = computed({ get: () => form.details.techStack?.join(', ') || '', set: value => { form.details.techStack = value.split(/[,，]/).map(s => s.trim()).filter(Boolean) } })
function keydown(e: KeyboardEvent) { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') { e.preventDefault(); if (!busy.value) save() } }
onMounted(() => window.addEventListener('keydown', keydown)); onUnmounted(() => window.removeEventListener('keydown', keydown))
async function verify(result: string) {
  if (!item.value || dirty.value || item.value.revisionState === 'editing') { message.warning('请先发布当前版本，再进行核验'); return }
  if (!await confirm('记录人工核验结果？', '仅对当前公开版本记录结果，内容更新后需要重新核验。')) return
  try { await api(`/api/admin/contents/${item.value.id}/verify`, { method: 'POST', body: { revisionId: item.value.revisionId, result, evidenceUrl: form.details.sourceUrl || '', note: '管理员人工核验' } }); message.success('核验结果已记录') } catch (e) { message.error(errorText(e)) }
}
</script>
<template><div class="editor-page"><div class="editor-topbar"><div class="editor-identity"><NuxtLink :to="`/admin/${sectionOf(form.type).path}`" class="editor-back" aria-label="返回列表" title="返回列表">←</NuxtLink><div class="editor-heading"><strong>{{ item ? '编辑' : '新建' }}{{ sectionOf(form.type).label }}</strong><div class="editor-state"><span class="state-badge" :class="item?.publishStatus || 'draft'">{{ statusText(item?.publishStatus || 'draft') }}</span><small role="status" :class="{ 'dirty-indicator': dirty }">{{ busy ? '正在保存…' : dirty ? '有未保存修改' : item ? '已保存' : '新草稿' }}</small></div></div></div><div class="admin-actions editor-actions"><div class="editor-view-actions"><button v-if="item" class="quiet" @click="history">版本</button></div><div class="editor-save-actions"><button :disabled="busy" title="保存草稿（Ctrl / ⌘ + S）" @click="save()">保存草稿</button><button class="primary" :disabled="busy" @click="save(true)">{{ item?.publishStatus === 'published' ? '更新发布' : '发布' }}</button></div></div></div><div class="editor-grid"><section class="studio-panel editor-paper"><label class="sr-only" for="content-title">标题</label><input id="content-title" v-model="form.title" class="editor-title" maxlength="200" placeholder="写下一个标题…"><label class="sr-only" for="content-summary">摘要</label><textarea id="content-summary" v-model="form.summary" class="editor-summary" maxlength="5000" placeholder="添加一段摘要…" rows="3" /><div class="editor-tabs"><button :class="{ active: !previewInline }" @click="previewInline = false">Markdown</button><button :class="{ active: previewInline }" @click="previewInline = true">阅读预览</button><small>{{ form.bodyMarkdown.length }} 字符</small></div><div v-if="!previewInline" class="editor-toolbar"><button @click="insert('## 小标题\n')" title="插入标题">H₂</button><button @click="insert('**加粗文字**')" title="插入加粗">B</button><button @click="insert('[链接文字](https://example.com)')" title="插入链接">↗ 链接</button><button @click="insert('\n```\n代码\n```\n')" title="插入代码">&lt;/&gt;</button><button @click="pick('body')">◫ 插入图片</button></div><textarea v-if="!previewInline" ref="bodyInput" v-model="form.bodyMarkdown" aria-label="正文" class="editor-body" maxlength="500000" placeholder="从这里开始，慢慢写下来…" /><MarkdownBody v-else :source="form.bodyMarkdown" preview /><div class="editor-bottom"><span>Ctrl / ⌘ + S 保存草稿</span><span>工作稿与公开版本独立</span></div>
      <section v-if="form.type === 'tutorial'" class="chapter-editor"><div class="panel-heading"><h2>教程章节</h2><button @click="addChapter">＋ 添加章节</button></div><article v-for="(c, index) in form.details.chapters" :key="c.chapterKey" class="chapter-editor-item"><div class="chapter-editor-head"><strong>第 {{ index + 1 }} 章</strong><div><button :disabled="index === 0" @click="moveChapter(index, -1)" :aria-label="`上移第${index + 1}章`">↑</button><button :disabled="index === form.details.chapters!.length - 1" @click="moveChapter(index, 1)" :aria-label="`下移第${index + 1}章`">↓</button><button class="danger" @click="form.details.chapters!.splice(index, 1)">移除</button></div></div><label :for="`chapter-title-${index}`">章节标题</label><input :id="`chapter-title-${index}`" v-model="c.title" maxlength="200"><label :for="`chapter-slug-${index}`">章节地址</label><input :id="`chapter-slug-${index}`" v-model="c.slug" maxlength="120"><label :for="`chapter-body-${index}`">章节正文</label><textarea :id="`chapter-body-${index}`" v-model="c.bodyMarkdown" rows="8" maxlength="200000" /></article><p v-if="!form.details.chapters?.length" class="admin-empty">整个教程与章节一起发布。先添加第一章吧。</p></section>
    </section><aside class="editor-settings"><section class="studio-panel"><h2>发布设置</h2><div class="field"><label>内容类型</label><NSelect v-model:value="form.type" :options="typeOptions" :disabled="!!item" aria-label="内容类型" /><small v-if="!item">先在这里选好类型，再慢慢写。</small></div><div v-if="item" class="field"><label for="content-slug">访问地址</label><input id="content-slug" v-model="form.slug" disabled placeholder="a-quiet-place" maxlength="160"><small>创建后固定，不可修改。</small></div><div v-else class="field"><label>访问地址</label><small style="margin:0">保存后自动生成数字编号（如 /articles/12），不用手填。</small></div><div v-if="form.type === 'article'" class="field"><label>&#20998;&#31867;</label><NSelect v-model:value="form.categoryId" :options="categories" clearable filterable placeholder="&#36873;&#25321;&#20998;&#31867;" aria-label="&#20869;&#23481;&#20998;&#31867;" /></div><div class="field"><label>标签</label><NSelect v-model:value="form.tagIds" :options="tags" multiple filterable placeholder="选择标签" aria-label="内容标签" /></div><NuxtLink to="/admin/taxonomy" class="text-link">&#31649;&#29702;&#20998;&#31867;&#19982;&#26631;&#31614; ↗</NuxtLink><div class="field"><label for="change-note">版本说明</label><input id="change-note" v-model="form.changeNote" maxlength="500" placeholder="记录这次修改的原因"></div><div class="help-note">保存草稿不会影响已发布内容；点击发布后，前台才会更新。</div></section><section class="studio-panel"><h2>封面图片</h2><img v-if="form.coverAssetId" class="editor-cover" :src="`/api/admin/media/${form.coverAssetId}/file`" alt="封面预览"><div class="admin-actions"><button @click="pick('cover')">选择封面</button><button v-if="form.coverAssetId" @click="form.coverAssetId = null">移除</button></div></section>
      <section v-if="form.type !== 'article'" class="studio-panel"><h2>{{ sectionOf(form.type).label }}信息</h2><template v-if="form.type === 'work'"><div class="field"><label for="demo-url">演示地址</label><input id="demo-url" v-model="form.details.demoUrl" type="url" placeholder="https://…"></div><div class="field"><label for="source-url">源码地址</label><input id="source-url" v-model="form.details.sourceUrl" type="url" placeholder="https://…"></div><div class="field"><label for="tech-stack">技术栈（逗号分隔）</label><input id="tech-stack" v-model="techText" placeholder="Vue, Java, PostgreSQL"></div><div class="field"><label for="project-status">项目状态</label><select id="project-status" v-model="form.details.projectStatus"><option value="planning">规划中</option><option value="developing">开发中</option><option value="released">已发布</option><option value="archived">已归档</option></select></div><button @click="pick('gallery')">＋ 添加作品截图</button><div class="editor-gallery"><div v-for="id in form.galleryAssetIds" :key="id"><img :src="`/api/admin/media/${id}/file`" alt="作品截图"><button aria-label="移除截图" @click="form.galleryAssetIds = form.galleryAssetIds.filter(x => x !== id)">×</button></div></div></template>
        <template v-if="form.type === 'tutorial'"><div class="field"><label for="difficulty">难度</label><select id="difficulty" v-model="form.details.difficulty"><option value="beginner">入门</option><option value="intermediate">进阶</option><option value="advanced">高级</option></select></div><div class="field"><label for="prerequisites">前置要求</label><textarea id="prerequisites" v-model="form.details.prerequisitesMarkdown" rows="5" /></div></template>

        <template v-if="form.type === 'deal'"><div class="field"><label for="deal-source">信息来源</label><input id="deal-source" v-model="form.details.sourceUrl" type="url" placeholder="https://…"></div><div class="field"><label for="claim-url">领取入口</label><input id="claim-url" v-model="form.details.claimUrl" type="url" placeholder="https://…"></div><div class="field"><label for="benefit">优惠或资源内容</label><input id="benefit" v-model="form.details.benefitText" maxlength="1000"></div><div class="field"><label for="requirements">适用条件与限制</label><textarea id="requirements" v-model="form.details.requirementsMarkdown" rows="5" /></div><div class="field"><label for="starts-at">开始时间（北京时间）</label><input id="starts-at" :value="datetime(form.details.startsAt)" type="datetime-local" @input="setDate('startsAt', $event)"></div><div class="field"><label for="ends-at">截止时间（北京时间）</label><input id="ends-at" :value="datetime(form.details.endsAt)" type="datetime-local" @input="setDate('endsAt', $event)"></div><div v-if="item?.publishStatus === 'published'" class="admin-actions"><button @click="verify('valid')">核验有效</button><button @click="verify('invalid')">标记失效</button></div></template>
      </section><NuxtLink v-if="item?.publishStatus === 'published'" :to="contentUrl(item)" target="_blank" class="button">查看公开版本 ↗</NuxtLink></aside></div>
    <MediaPicker v-model:show="picker" @select="chosen" /><NModal v-model:show="showHistory" preset="card" title="内容版本" style="width:min(700px,calc(100% - 30px))"><p class="admin-footnote">已发布版本保持冻结，新的修改保存在独立工作稿中。</p><div v-for="r in revisions" :key="r.id" class="revision-row"><strong>第 {{ r.revisionNo }} 版 · {{ r.title || '未命名' }}</strong><span>{{ statusText(r.revisionState) }}</span><p>{{ r.changeNote || '没有版本说明' }}</p></div></NModal>
  </div></template>
